{"point":{"id":"diagrams","title":"Immutable Diagram Revisions","rationale":"Diagram identity, parsed ASCII content, logical node continuity, source mappings, and revision ancestry meet here. Creation and editing issue validated immutable revisions; the runtime registry preserves their identity. This separates diagram content from its placements and provides the shared foundation for editing, generation, comparison, and persistence.","sourcePaths":["domain/core/diagrams/diagram.ts","domain/core/diagrams/diagramContent.ts","domain/core/diagrams/diagramContentNodes.ts","domain/core/diagrams/asciiTree.ts","domain/core/diagrams/diagramRevision.ts","domain/core/diagrams/diagramRevisionEditor.ts","domain/core/diagrams/diagramRevisionStore.ts","domain/core/diagrams/submitDiagramEdit.ts"],"relationships":[]},"sources":[{"path":"domain/core/diagrams/diagram.ts","text":"import { validateDiagramHighlights, type DiagramHighlight } from './diagramHighlight';
import type { DeepReadonly } from '../immutability';
import { validateDiagramJumps, type DiagramJump } from './diagramJump';
import { buildDiagramContent, contentParserVersion, type DiagramContent } from './diagramContent';
import { validateDiagramLocalMappings } from './diagramMappings';
import { mappingsForSelection } from './diagramSelection';
import { asciiSha256 } from './asciiSha256';
import type { DiagramElementMapping } from '../records/domain';
import type { CorpusBinding, BuiltInDomainProfileId } from '../profiles/domainProfile';
import type { ProjectRepresentationEvidenceRecord } from '../representations/projectCatalog';

export interface DiagramSourceBinding {
  sourceId: string;
  repositoryIdentity: string;
  corpus: CorpusBinding;
  domainProfileId: BuiltInDomainProfileId;
}
export type DiagramSourceContext = DeepReadonly<{
  binding?: DiagramSourceBinding;
  contentHash: string;
  mappings: readonly DiagramElementMapping[];
  evidence: Record<string, ProjectRepresentationEvidenceRecord>;
}>;
/** Repository-independent diagram, shared by canvas, persistence, and agents. */
export interface Diagram {
  /** Stable service identity; id remains the local canvas content key. */
  readonly diagramId: string;
  readonly revisionId: string;
  readonly id: string;
  readonly revision: number;
  readonly content: DeepReadonly<DiagramContent>;
  readonly sourceContext: DeepReadonly<DiagramSourceContext>;
  readonly highlights?: DeepReadonly<DiagramHighlight[]>;
  readonly jumps?: DeepReadonly<DiagramJump[]>;
}
export interface DiagramInput {
  id: string; revision: number; ascii: string; structureKind?: 'diagram' | 'tree';
  mappings?: readonly DiagramElementMapping[];
  evidence?: DiagramSourceContext['evidence'];
  source?: DiagramSourceBinding;
  highlights?: readonly DiagramHighlight[];
  jumps?: readonly DiagramJump[];
}
export function validateSourceBinding(binding: DiagramSourceBinding): void {
  if (!binding || typeof binding.sourceId !== 'string' || !binding.sourceId || binding.sourceId.length > 200
    || typeof binding.repositoryIdentity !== 'string' || !binding.repositoryIdentity
    || !['source-code','document'].includes(binding.domainProfileId) || !binding.corpus
    || !['git-worktree','filesystem-documents'].includes(binding.corpus.kind)
    || typeof binding.corpus.root !== 'string' || !/^(?:\/|[A-Za-z]:[\\/])/.test(binding.corpus.root)
    || (binding.domainProfileId === 'source-code') !== (binding.corpus.kind === 'git-worktree')) throw new Error('Invalid diagram source binding');
}
export function validateDiagram(diagram: Diagram): void {
  if (diagram?.content && (!diagram.diagramId || !diagram.revisionId))
    throw new Error('Diagram storage migration required: saved diagrams lack service identities. Run the offline diagram identity migration before loading this store.');
  if (!diagram || typeof diagram.diagramId !== 'string' || !diagram.diagramId.startsWith('diagram-') || typeof diagram.revisionId !== 'string' || !diagram.revisionId.startsWith('diagram-revision-') || typeof diagram.id !== 'string' || !diagram.id || !Number.isInteger(diagram.revision) || diagram.revision < 0 || !diagram.content) throw new Error('Invalid diagram');
  if (['ascii','mappings','diagramContent','structureKind'].some(key => Object.hasOwn(diagram,key))) throw new Error('Diagram data must live in content and sourceContext');
  const { content, sourceContext: source } = diagram;
  const canonical = buildDiagramContent(content.ascii, `${diagram.id}:${diagram.revision}`, content.structure.kind, contentParserVersion(content.structure));
  if (JSON.stringify(content) !== JSON.stringify(canonical)) throw new Error('Invalid diagram content revision or parsed structure');
  if (!source || !source.evidence || !Array.isArray(source.mappings) || source.contentHash !== asciiSha256(content.ascii)) throw new Error('Diagram source context does not match content');
  if (source.binding) validateSourceBinding(source.binding);
  validateDiagramJumps(content, diagram.jumps);
  validateDiagramHighlights(diagram.highlights);
  validateDiagramLocalMappings(content.ascii, source.mappings);
  for (const [id, entry] of Object.entries(source.evidence)) {
    if (entry?.sourceId && source.binding && entry.sourceId !== source.binding.sourceId) throw new Error('Evidence belongs to another diagram source');
    if (!entry || entry.id !== id || typeof entry.label !== 'string' || !Array.isArray(entry.sourceRanges)) throw new Error('Invalid diagram evidence');
    for (const range of entry.sourceRanges) {
      if (!range || typeof range.id !== 'string' || typeof range.path !== 'string' || range.path.startsWith('/') || range.path.split(/[\\/]/).includes('..')
        || !Number.isInteger(range.startLine) || range.startLine < 1 || !Number.isInteger(range.endLine) || range.endLine < range.startLine
        || !Array.isArray(range.originalLines) || range.originalLines.length !== range.endLine - range.startLine + 1 || range.originalLines.some((line: unknown) => typeof line !== 'string')) throw new Error('Invalid diagram evidence range');
    }
  }
  for (const mapping of source.mappings) {
    const range = source.evidence[mapping.entityId]?.sourceRanges[mapping.sourceRangeIndex];
    if (!range || mapping.sourceRangeId && mapping.sourceRangeId !== range.id) throw new Error('Mapping references unknown diagram evidence');
  }
}
/** All mapping/evidence joins live here; callers receive derived, read-only results. */
export function diagramSource(diagram: Diagram) {
  return queryDiagramSourceContext(diagram.sourceContext);
}
export function queryDiagramSourceContext(context: DiagramSourceContext) {
  const evidenceFor = (mapping: DiagramElementMapping) => {
    const entity = context.evidence[mapping.entityId];
    const range = entity?.sourceRanges[mapping.sourceRangeIndex];
    return { mapping, entity, range, binding: context.binding };
  };
  return {
    context,
    mappings: () => context.mappings,
    forSelection: (rect: Parameters<typeof mappingsForSelection>[1]) => mappingsForSelection(context.mappings, rect).map(evidenceFor),
    entries: () => context.mappings.map(evidenceFor),
    search: (query: string) => {
      const q = query.toLowerCase();
      return context.mappings.map(evidenceFor).filter(({mapping,entity,range}) => [mapping.entityId,entity?.label,range?.path,range?.symbol].some(value=>value?.toLowerCase().includes(q)));
    }
  };
}
export function sourceBindingFromLocation(location: { checkoutRoot: string; repositoryIdentity: string; domainProfileId?: BuiltInDomainProfileId; corpus?: CorpusBinding; gitRevision?: string }): DiagramSourceBinding {
  const corpus = location.corpus ?? { kind: 'git-worktree' as const, root: location.checkoutRoot, ...(location.gitRevision ? {revision:location.gitRevision} : {}) };
  return { sourceId: `source-${asciiSha256(`${corpus.kind}:${corpus.root}`).slice(0,24)}`, repositoryIdentity: location.repositoryIdentity,
    corpus, domainProfileId: location.domainProfileId ?? 'source-code' };
}
"},{"path":"domain/core/diagrams/diagramContent.ts","text":"import type { DeepReadonly } from '../immutability';
import { asciiSha256 } from './asciiSha256';
import { parseAsciiTree } from './asciiTree';

export type DiagramContentNodeSpan = DeepReadonly<{ line: number; startColumn: number; endColumn: number }>;
export type DiagramContentNode = DeepReadonly<{
  id: string; label: string;
  /** @deprecated As geometry: first line only (still the node's anchor for identity matching). Use `contentNodeSpans`/`contentNodeRect` from contentNodeGeometry.ts. */
  line: number;
  branchColumn: number;
  /** @deprecated As geometry: first line only (still the node's anchor for identity matching). Use `contentNodeSpans`/`contentNodeRect` from contentNodeGeometry.ts. */
  startColumn: number;
  /** @deprecated As geometry: first line only (still the node's anchor for identity matching). Use `contentNodeSpans`/`contentNodeRect` from contentNodeGeometry.ts. */
  endColumn: number;
  /** One span per text line (1-based, inclusive). Absent on single-line tree nodes stored before spans existed. */
  lines?: DiagramContentNodeSpan[];
  parentId?: string; childIds: string[]; foldRanges: { startLine: number; endLine: number }[];
}>;
export type DiagramContent = DeepReadonly<{
  revisionId: string; ascii: string; asciiSha256: string;
  /**
   * Unstructured diagrams derive their content nodes. `parserVersion` pins that derivation: stored revisions key
   * `nodeRefs` by the derived node IDs, so content without a version keeps the legacy interpreter forever.
   */
  structure: { kind: 'diagram'; parserVersion?: 'ascii-graph-1' } | { kind: 'tree'; parserVersion: 'ascii-tree-1' | 'ascii-tree-2'; rootIds: string[]; nodes: Record<string, DiagramContentNode> };
}>;
export type DiagramParserVersion = 'ascii-tree-1' | 'ascii-tree-2' | 'ascii-graph-1' | 'legacy-diagram';
/** The parser version a rebuild of this content must use to reproduce the same structure and node IDs. */
export function contentParserVersion(structure: DiagramContent['structure']): DiagramParserVersion {
  return structure.kind === 'tree' ? structure.parserVersion : structure.parserVersion ?? 'legacy-diagram';
}
/** New content uses the current parser for its kind; rebuilds pass `contentParserVersion` of the content they reproduce. */
export function buildDiagramContent(ascii: string, revisionId: string, kind: 'diagram' | 'tree' = 'diagram', version?: DiagramParserVersion): DiagramContent {
  const parserVersion = version ?? (kind === 'tree' ? 'ascii-tree-2' : 'ascii-graph-1');
  if (kind === 'tree' && parserVersion !== 'ascii-tree-1' && parserVersion !== 'ascii-tree-2') throw new Error('Unknown tree parser version');
  if (kind === 'diagram' && parserVersion !== 'ascii-graph-1' && parserVersion !== 'legacy-diagram') throw new Error('Unknown diagram parser version');
  // A blank rectangular diagram reserves editable canvas space (e.g. a generated-diagram placeholder).
  const lines = ascii.split('\n');
  const blankRectangle = kind === 'diagram' && lines.length > 1 && lines[0].length > 0
    && lines.every(line => line.length === lines[0].length && /^ +$/.test(line));
  if ((!ascii.trim() && !blankRectangle) || ascii.length > 20000 || /[^\x20-\x7e\n]/.test(ascii)) throw new Error('Diagram must contain 1–20000 printable ASCII characters with LF newlines');
  const content: DiagramContent = { revisionId, ascii, asciiSha256: asciiSha256(ascii),
    structure: parserVersion === 'ascii-graph-1' ? { kind: 'diagram', parserVersion } : { kind: 'diagram' } };
  if (kind === 'diagram') return content;
  const treeVersion = parserVersion as 'ascii-tree-1' | 'ascii-tree-2';
  const parsed = parseAsciiTree(ascii, treeVersion);
  const ids = new Map(parsed.map(node => [node.line, `${revisionId}:${content.asciiSha256}:line-${node.line}`]));
  const nodes: Record<string, DiagramContentNode> = {};
  for (const node of parsed) {
    const id = ids.get(node.line)!;
    const peer = parsed.find(next => next.line > node.line && next.branchColumn <= node.branchColumn);
    nodes[id] = { id, label: node.text, line: node.line, branchColumn: node.branchColumn, startColumn: node.textColumn,
      endColumn: node.textColumn + Math.max(1, node.text.length) - 1,
      parentId: node.parentLine === undefined ? undefined : ids.get(node.parentLine),
      childIds: parsed.filter(child => child.parentLine === node.line).map(child => ids.get(child.line)!),
      foldRanges: node.descendantLines.length ? [{ startLine: node.line + 1, endLine: peer ? peer.line - 1 : ascii.split('\n').length }] : [] };
  }
  return { ...content, structure: { kind: 'tree', parserVersion: treeVersion, rootIds: Object.values(nodes).filter(node => !node.parentId).map(node => node.id), nodes } };
}
export function visibleContentLines(content: DiagramContent, collapsedIds: readonly string[]): number[] {
  const hidden = new Set<number>();
  if (content.structure.kind === 'tree') for (const id of collapsedIds) {
    const node = content.structure.nodes[id];
    if (!node) throw new Error('STALE_CONTENT_NODE');
    for (const range of node.foldRanges) for (let line = range.startLine; line <= range.endLine; line++) hidden.add(line);
  }
  return content.ascii.split('\n').map((_, i) => i + 1).filter(line => !hidden.has(line));
}

export function contentTreeNodes(content: DiagramContent): import('./asciiTree').AsciiTreeNode[] {
  if (content.structure.kind !== 'tree') return [];
  const nodes = content.structure.nodes;
  return Object.values(nodes).map(node => ({ line: node.line, branchColumn: node.branchColumn, textColumn: node.startColumn, text: node.label,
    parentLine: node.parentId ? nodes[node.parentId]?.line : undefined,
    descendantLines: Object.values(nodes).filter(child => node.foldRanges.some(range => child.line >= range.startLine && child.line <= range.endLine)).map(child => child.line) }));
}
"},{"path":"domain/core/diagrams/diagramContentNodes.ts","text":"import { deepFreeze } from '../immutability';
import type { DiagramContent, DiagramContentNode } from './diagramContent';
import { parseAsciiGraph } from './asciiGraph/parseAsciiGraph';
import { parseDiagram } from './interpreter';

// A derived index lets existing unstructured diagrams expose anchors without rewriting their content.
const indexes = new WeakMap<DiagramContent, readonly DiagramContentNode[]>();
export function diagramContentNodes(content: DiagramContent): readonly DiagramContentNode[] {
  if (content.structure.kind === 'tree') return Object.values(content.structure.nodes);
  const cached = indexes.get(content);
  if (cached) return cached;
  const nodes = content.structure.parserVersion === 'ascii-graph-1' ? graphNodes(content) : legacyNodes(content);
  deepFreeze(nodes);
  indexes.set(content, nodes);
  return nodes;
}

/** Content without a parser version keeps the interpreter-derived nodes its stored nodeRefs were keyed by. */
function legacyNodes(content: DiagramContent): DiagramContentNode[] {
  const parsed = parseDiagram(content.ascii, { dialect: 'mixed', repairs: 'none', continuation: 'separate' });
  const scoped = (id: string) => `${content.revisionId}:${content.asciiSha256}:${id}`;
  return parsed.nodes.filter(node => node.spans.length).map(node => ({
    id: scoped(node.id), label: node.label, line: node.spans[0].line,
    branchColumn: node.branchColumn ?? node.spans[0].column,
    startColumn: node.spans[0].column, endColumn: node.spans[0].endColumn - 1,
    parentId: node.parentId ? scoped(node.parentId) : undefined,
    childIds: node.childIds.map(scoped), foldRanges: []
  }));
}

function graphNodes(content: DiagramContent): DiagramContentNode[] {
  const graph = parseAsciiGraph(content.ascii);
  // IDs keep the earlier `node-<line>-<column>` form of a box's first span, so saved single-line references still resolve.
  const localId = new Map(graph.boxes.map(box => [box.id, `node-${box.lines[0].line}-${box.lines[0].col1}`]));
  const scoped = (id: string) => `${content.revisionId}:${content.asciiSha256}:${localId.get(id)}`;
  return graph.boxes.map((box): DiagramContentNode => ({
    id: scoped(box.id), label: box.text, line: box.lines[0].line,
    branchColumn: box.rect.col1, startColumn: box.lines[0].col1, endColumn: box.lines[0].col2,
    lines: box.lines.map(span => ({ line: span.line, startColumn: span.col1, endColumn: span.col2 })),
    parentId: box.parentId ? scoped(box.parentId) : undefined,
    childIds: box.childIds.map(scoped), foldRanges: []
  }));
}
"},{"path":"domain/core/diagrams/asciiTree.ts","text":"import { parseDiagram } from './interpreter';

export interface AsciiTreeNode {
  line: number;
  branchColumn: number;
  textColumn: number;
  text: string;
  parentLine?: number;
  descendantLines: number[];
}

/** Compatibility projection of the shared spatial interpreter for existing tree consumers. */
export function parseAsciiTree(ascii: string, compatibility: 'ascii-tree-1' | 'ascii-tree-2' = 'ascii-tree-2'): AsciiTreeNode[] {
  const parsed = parseDiagram(ascii, { dialect: 'tree', compatibility,
    treeTolerance: 0, wireTolerance: 0, continuation: 'separate', repairs: 'none' });
  const lines = new Map(parsed.nodes.map(node => [node.id, node.spans[0].line]));
  const nodes = parsed.nodes.map((node): AsciiTreeNode => ({
    line: node.spans[0].line, branchColumn: node.branchColumn === undefined ? -1 : node.branchColumn - 1,
    textColumn: node.spans[0].column, text: node.label,
    ...(node.parentId ? { parentLine: lines.get(node.parentId) } : {}), descendantLines: []
  }));
  const byLine = new Map(nodes.map(node => [node.line, node]));
  for (const node of nodes) {
    let parent = node.parentLine === undefined ? undefined : byLine.get(node.parentLine);
    while (parent) {
      parent.descendantLines.push(node.line);
      parent = parent.parentLine === undefined ? undefined : byLine.get(parent.parentLine);
    }
  }
  return nodes;
}

export function asciiTreeLineage(ascii: string, line: number): AsciiTreeNode[] {
  const nodes = parseAsciiTree(ascii);
  const byLine = new Map(nodes.map((node) => [node.line, node]));
  const lineage: AsciiTreeNode[] = [];
  let node = byLine.get(line);
  while (node) {
    lineage.unshift(node);
    node = node.parentLine === undefined ? undefined : byLine.get(node.parentLine);
  }
  return lineage;
}

/** Return a node and all of its descendants in display (pre-order) order. */
export function asciiTreeSubtree(ascii: string, line: number): AsciiTreeNode[] {
  const nodes = parseAsciiTree(ascii);
  const root = nodes.find((node) => node.line === line);
  if (!root) return [];
  const descendantLines = new Set(root.descendantLines);
  return nodes.filter((node) => node.line === line || descendantLines.has(node.line));
}

export function hiddenAsciiTreeLines(
  ascii: string,
  collapsedNodeLines: ReadonlySet<number>
): Set<number> {
  const lines = ascii.replace(/\r\n?/g, "\n").split("\n");
  const nodes = parseAsciiTree(ascii);
  const hidden = new Set<number>();
  for (const node of nodes) {
    if (!collapsedNodeLines.has(node.line) || node.descendantLines.length === 0) continue;
    const nextPeer = nodes.find((candidate) => (
      candidate.line > node.line && candidate.branchColumn <= node.branchColumn
    ));
    const endLine = nextPeer ? nextPeer.line - 1 : lines.length;
    for (let line = node.line + 1; line <= endLine; line += 1) hidden.add(line);
  }
  return hidden;
}
"},{"path":"domain/core/diagrams/diagramRevision.ts","text":"import { deepFreeze } from '../immutability';
import { validateDiagram, type DiagramInput } from './diagram';
import { DiagramRevisionEditor, type DiagramRevision, type DiagramEdit, type PreparedDiagramEdit } from './diagramRevisionEditor';
import { diagramContentNodes } from './diagramContentNodes';
import type { SubtreeRange } from './diagramSubtreeEdit';
export type { DiagramRevision, DiagramEdit, DiagramRevisionId } from './diagramRevisionEditor';
export interface DiagramRevisionResult extends PreparedDiagramEdit { readonly revision: DiagramRevision; replacementRanges?: SubtreeRange[] }
export type DiagramRevisionSummary = Readonly<Pick<DiagramRevision, 'id' | 'diagramId' | 'parentId'>>;

// Domain operations return immutable revisions. Persistence/publication is explicit.
export function createDiagram(input: DiagramInput): DiagramRevisionResult {
  const prepared = new DiagramRevisionEditor({}, () => ({})).prepareCreate(input);
  return issueDiagramRevision(prepared);
}
export function reviseDiagram(base: DiagramRevision, edit: DiagramEdit): DiagramRevisionResult {
  const prepared = new DiagramRevisionEditor({ [base.id]: base }, () => ({ [base.diagram.id]: base.id }))
    .prepareEdit('edit', base.diagram.id, edit);
  if (prepared.diagram === base.diagram) return { ...prepared, revision: base };
  return issueDiagramRevision({ ...prepared, diagram: { ...prepared.diagram, diagramId: base.diagramId, revisionId: `diagram-revision-${crypto.randomUUID()}` } }, base);
}
export function deriveDiagram(base: DiagramRevision, input: Omit<DiagramInput, 'id' | 'revision'>, refs: Record<string, number>, sources: readonly DiagramRevision[]) {
  const allowed = new Set<string>();
  for (const source of sources) {
    if (source.diagramId !== base.diagramId) throw Error('Identity source belongs to another diagram');
    Object.values(source.nodeRefs).forEach(ref => allowed.add(ref));
  }
  const editor = new DiagramRevisionEditor({ [base.id]: base }, () => ({ [base.diagram.id]: base.id }));
  const prepared = editor.prepareEdit('derive', base.diagram.id, { kind: 'replace', input,
    nodeCorrespondence: Object.fromEntries(Object.entries(refs).filter(([ref]) => Object.values(base.nodeRefs).includes(ref))) });
  const nodes = diagramContentNodes(prepared.diagram.content), identities = new Map<string, string>();
  for (const [ref, line] of Object.entries(refs)) {
    const matching = nodes.filter(node => node.line === line);
    if (!allowed.has(ref) || matching.length !== 1 || identities.has(matching[0].id)) throw Error('Invalid derived node identity');
    identities.set(matching[0].id, ref);
  }
  return issueDiagramRevision({ ...prepared, diagram: { ...prepared.diagram, diagramId: base.diagramId, revisionId: `diagram-revision-${crypto.randomUUID()}` } }, base, identities);
}
function issueDiagramRevision(prepared: PreparedDiagramEdit, base?: DiagramRevision, identities = new Map<string, string>()): DiagramRevisionResult {
  const reverse = new Map([...prepared.nodeIds].map(([old, next]) => [next, old]));
  const record = deepFreeze({ id: prepared.diagram.revisionId, diagramId: prepared.diagram.diagramId,
    ...(base ? { parentId: base.id } : {}), diagram: prepared.diagram,
    nodeRefs: Object.fromEntries(diagramContentNodes(prepared.diagram.content).map(node => {
      const old = reverse.get(node.id);
      return [node.id, identities.get(node.id) || old && base?.nodeRefs[old] || `node-${crypto.randomUUID()}`];
    })) });
  validateDiagram(record.diagram);
  return { ...prepared, diagram: record.diagram, revision: record };
}
"},{"path":"domain/core/diagrams/diagramRevisionEditor.ts","text":"import { validateDiagramHighlights, rebaseDiagramHighlights, type DiagramHighlight } from './diagramHighlight';
import { validateDiagram, type Diagram, type DiagramInput } from './diagram';
import { constructDiagram } from './internal/constructDiagram';
import { patchDiagramRanges } from './patchDiagram';
import { retainSourceMappings } from './retainSourceMappings';
import { diagramContentNodes } from './diagramContentNodes';
import { activeDiagramJumps, rebaseDiagramJumps, validateDiagramJumps, type DiagramJump } from './diagramJump';

export type ContextId = string;
export type DiagramRevisionId = string;
export interface DiagramRevision {
  readonly id: DiagramRevisionId;
  readonly diagramId: string;
  readonly parentId?: DiagramRevisionId;
  /** Immutable diagram payload. Never returned by resolve(). */
  readonly diagram: Diagram;
  readonly nodeRefs: Readonly<Record<string, string>>;
}
export interface DiagramView {
  id: string;
  ascii: string;
  asciiSha256: string;
  structureKind: 'diagram' | 'tree';
  nodes: ReturnType<typeof diagramContentNodes>;
  sourceContext: Diagram['sourceContext'];
  jumps: { id: string; source: Omit<DiagramJump['source'], 'revisionId' | 'contentHash'>; target: DiagramJump['target'] }[];
}
export interface PreparedDiagramEdit {
  readonly diagram: Diagram;
  readonly nodeIds: ReadonlyMap<string, string>;
  lineAfter?: (line: number) => number | undefined;
}
export type DiagramEdit =
  | { kind: 'source-mappings'; expectedContentHash: string; mappings: NonNullable<DiagramInput['mappings']>; evidence: NonNullable<DiagramInput['evidence']>; source?: DiagramInput['source'] }
  | { kind: 'patch'; start: number; end: number; patch: string; mappings?: DiagramInput['mappings']; nodeCorrespondence?: Record<string, number> }
  | { kind: 'patches'; retainMappings?: boolean; patches: { start: number; end: number; patch: string[] }[]; mappings?: DiagramInput['mappings']; nodeCorrespondence?: Record<string, number> }
  | { kind: 'replace'; retainMappings?: boolean; input: Omit<DiagramInput, 'id' | 'revision'>; nodeCorrespondence?: Record<string, number> }
  | { kind: 'jumps'; jumps: DiagramJump[] }
  | { kind: 'highlights'; highlights: DiagramHighlight[] };

/** Canonical content ownership; context bindings are supplied by canvas history. */
export interface DiagramRevisionOperations {
  resolve(contextId: ContextId, diagramId: string): DiagramView;
  prepareCreate(input: DiagramInput): PreparedDiagramEdit;
  prepareEdit(contextId: ContextId, diagramId: string, edit: DiagramEdit): PreparedDiagramEdit;
  merge(baseline: Readonly<Record<string, DiagramRevisionId>>, current: Readonly<Record<string, DiagramRevisionId>>,
    proposed: Readonly<Record<string, DiagramRevisionId>>): Record<string, DiagramRevisionId>;
}

export class DiagramRevisionEditor implements DiagramRevisionOperations {
  constructor(private readonly revisions: Record<string, DiagramRevision>,
    private readonly bindings: (contextId: ContextId) => Readonly<Record<string, DiagramRevisionId>>) {}

  private revision(contextId: ContextId, diagramId: string): DiagramRevision {
    const id = this.bindings(contextId)[diagramId], revision = id && this.revisions[id];
    if (!revision || revision.diagram.id !== diagramId) throw new Error(`Unknown diagram: ${diagramId}`);
    return revision;
  }
  resolve(contextId: ContextId, diagramId: string): DiagramView {
    const { diagram, nodeRefs } = this.revision(contextId, diagramId);
    const nodes = diagramContentNodes(diagram.content).map(node => ({ ...node, id: nodeRefs[node.id],
      parentId: node.parentId ? nodeRefs[node.parentId] : undefined, childIds: node.childIds.map(id => nodeRefs[id]) }));
    return structuredClone({ id: diagramId, ascii: diagram.content.ascii, asciiSha256: diagram.content.asciiSha256,
      structureKind: diagram.content.structure.kind, nodes, sourceContext: diagram.sourceContext,
      jumps: activeDiagramJumps(diagram.content, diagram.jumps).map(jump => {
